import './ProductCard.css';

const ProductCard = () => {
    return (
        <>        
            <div className="card-border">
                <div className="circle">
                    <div style={{padding: "13px 10px", fontWeight: "500"}}>
                        <div>Product</div> 
                        <div>Image</div>
                    </div>
                </div>
            </div>
        </>
    );
};

export default ProductCard;
